<?php require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/header.php';?><main class="section"><div class="head"><h2>Sua sacola</h2></div><?php if(!cart()):?><p>Sua sacola está vazia. <a href="catalog.php">Ver produtos →</a></p><?php else:?><table class="carttable"><tr><th>Produto</th><th>Detalhes</th><th>Qtd.</th><th>Total</th><th></th></tr><?php foreach(cart() as $k=>$i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['size'])?> <?=e($i['color'])?></td><td><?=e($i['quantity'])?></td><td><?=money($i['price']*$i['quantity'])?></td><td><form method="post" action="cart_remove.php"><input type="hidden" name="key" value="<?=e($k)?>"><button>Remover</button></form></td></tr><?php endforeach;?></table><h2 style="text-align:right">Total: <?=money(cart_total())?></h2><div style="text-align:right"><a class="buy" style="display:inline-block;width:auto" href="checkout.php">Finalizar pedido</a></div><?php endif;?></main><?php require __DIR__.'/includes/footer.php';
